@if($canManage)<div class="grid gap-4 lg:grid-cols-2"><x-ui.panel><h2 class="mb-4 font-bold text-blue-900">إضافة مرحلة</h2><form wire:submit="addPhase" class="space-y-3"><flux:input label="اسم المرحلة" wire:model="phase.title"/><flux:input type="date" label="البداية" wire:model="phase.start_date"/><flux:input type="date" label="النهاية" wire:model="phase.end_date"/><flux:button type="submit" icon="plus">إضافة مرحلة</flux:button></form></x-ui.panel><x-ui.panel><h2 class="mb-4 font-bold text-blue-900">إضافة مهمة</h2><form wire:submit="addTask" class="grid gap-3 sm:grid-cols-2"><flux:input label="المهمة" wire:model="task.title"/><flux:select label="المرحلة" wire:model="task.phase_id"><option value="">اختر المرحلة</option>@foreach($progress['phases'] as $p)<option value="{{ $p->id }}">{{ $p->title }}</option>@endforeach</flux:select><flux:select label="المكلف" wire:model="task.assigned_to"><option value="">اختر عضو الفريق</option>@foreach($users as $u)@if($u['id']==$project->manager_id||in_array($u['id'],$form['members']))<option value="{{ $u['id'] }}">{{ $u['name'] }}</option>@endif @endforeach</flux:select><flux:input type="date" label="البداية" wire:model="task.start_date"/><flux:input type="date" label="النهاية" wire:model="task.end_date"/><flux:input label="ملاحظات" wire:model="task.notes"/><flux:button type="submit" icon="plus">{{ $editingTask?'حفظ تعديل المهمة':'إضافة مهمة' }}</flux:button></form></x-ui.panel></div>@endif
<x-ui.panel><h2 class="mb-4 font-bold text-blue-900">المراحل والمهام</h2>@foreach($progress['phases'] as $p)<div wire:key="phase-{{ $p->id }}" class="mb-5 rounded-xl border border-blue-100 p-4"><div class="mb-3 flex justify-between font-bold"><span>{{ $p->title }}</span><span class="text-teal-700">{{ number_format((float)$p->progress,2) }}% · {{ $p->complete }}/{{ $p->total }}</span></div>@foreach($tasks->where('phase_id',$p->id) as $t)<div wire:key="task-{{ $t->id }}" class="flex flex-wrap items-center justify-between gap-3 border-t py-3"><span>{{ $t->title }}</span><span class="text-sm text-slate-500">{{ $t->end_date }}</span><span>{{ ['pending'=>'لم تبدأ','in_progress'=>'قيد التنفيذ','completed'=>'مكتملة','cancelled'=>'ملغاة'][$t->status] }}</span>@if($canManage||$t->assigned_to==auth()->id())<div class="flex gap-1">@if($canManage)<flux:button size="sm" wire:click="editTask({{ $t->id }})">تعديل</flux:button>@endif @foreach(['pending'=>'إعادة فتح','in_progress'=>'بدء','completed'=>'إكمال','cancelled'=>'إلغاء'] as $state=>$label)@if($t->status!==$state)<flux:button size="sm" wire:click="taskStatus({{ $t->id }},{{ $t->version }},'{{ $state }}')">{{ $label }}</flux:button>@endif @endforeach</div>@endif</div>@endforeach</div>@endforeach</x-ui.panel>
